The following code snippet worked for me.   First, we need to update the container spec then we need to update container cgroup resources using the task update.

````go     
    filter := containerId
	ctrs, err := client.Containers(ctx, filter)
	if err != nil {
		log.Error("Failed to query container with filter: ", filter)
		return
	}

	for _, ctr := range ctrs {
		if containerId != ctr.ID() {
			continue
		}
		spec, err := ctr.Spec(ctx)
		if err != nil {
			log.Error("Failed to get the Spec for container with ID: ", containerId)
			continue
		}
		opt := containerd.WithSpec(spec, oci.WithCPUs("10-23"))
		// Update container spec first.
		if err = ctr.Update(ctx, containerd.UpdateContainerOpts(opt)); err != nil {
			log.Error("Failed to update cpuset_cpus container with ID: ", containerId)
			continue
		}
		t, e := ctr.Task(ctx, nil)
		if e != nil {
			log.Error("Error while creating task ", e)
			continue
		}
		// Get the updated spec
		updatedSpec, err := ctr.Spec(ctx)
		if err != nil {
			log.Error("Failed to get the updated spec for container with ID: ", containerId)
			continue
		}
		// Update container cgroup resources using the task update
		if e := t.Update(ctx, containerd.WithResources(updatedSpec.Linux.Resources)); e != nil {
			log.Errorf("Error while updating resources for container id: %s err: %v", containerId, e)
			continue
		} else {
			log.Infof("Updated cpuset_cpus for container id: %s to: %s", containerId, cpuIsolation[cpuAffinityRule])
		}
	}
````

